#include "TFGLevelThreeDirector.h"
#include "GameFramework/PlayerController.h"
#include "Kismet/GameplayStatics.h"
#include "TFGCharacterBase.h"
#include "TFGObjectiveWidget.h"
#include "TFGQuestComponent.h"
ATFGLevelThreeDirector::ATFGLevelThreeDirector(){PrimaryActorTick.bCanEverTick=false;}void ATFGLevelThreeDirector::BeginPlay(){Super::BeginPlay();InitializeMission();}void ATFGLevelThreeDirector::InitializeMission(){auto*C=Cast<ATFGCharacterBase>(UGameplayStatics::GetPlayerCharacter(this,0));if(!C||!C->GetQuestComponent())return;PlayerCharacter=C;QuestComponent=C->GetQuestComponent();QuestComponent->OnQuestChanged.AddDynamic(this,&ATFGLevelThreeDirector::HandleQuestChanged);FTFGQuestState S;if(!QuestComponent->GetQuestState(QuestId,S)){QuestComponent->StartQuest(QuestId);S.QuestId=QuestId;S.Stage=0;S.bCompleted=false;}if(auto*PC=UGameplayStatics::GetPlayerController(this,0)){ObjectiveWidget=CreateWidget<UTFGObjectiveWidget>(PC,UTFGObjectiveWidget::StaticClass());if(ObjectiveWidget)ObjectiveWidget->AddToViewport(20);}if(S.bCompleted||S.Stage>=6)FinishMission();else ApplyObjectiveForStage(S.Stage);}void ATFGLevelThreeDirector::HandleQuestChanged(FName Id,int32 Stage){if(Id!=QuestId)return;FTFGQuestState S;if(auto*Q=QuestComponent.Get()){if(Q->GetQuestState(QuestId,S)&&(S.bCompleted||Stage>=6)){FinishMission();return;}}ApplyObjectiveForStage(Stage);}void ATFGLevelThreeDirector::ApplyObjectiveForStage(int32 Stage){if(!ObjectiveWidget)return;FText O;switch(Stage){case 0:O=FText::FromString(TEXT("Reach the royal avenue through the damaged streets."));break;case 1:O=FText::FromString(TEXT("Clear the Veyr soldiers holding the palace approach."));break;case 2:O=FText::FromString(TEXT("Investigate the Aetherian shard reacting to your presence."));break;case 3:O=FText::FromString(TEXT("Survive the heavy assault at the palace steps."));break;case 4:O=FText::FromString(TEXT("Activate the old defensive ward inside the outer court."));break;case 5:O=FText::FromString(TEXT("Reach the royal hall before the inner doors fall."));break;default:O=FText::FromString(TEXT("The inner palace route is open."));break;}ObjectiveWidget->SetObjective(FText::FromString(TEXT("LEVEL 3 — PALACE UNDER SIEGE")),O);ObjectiveWidget->SetObjectiveVisible(true);}void ATFGLevelThreeDirector::FinishMission(){if(bFinished)return;bFinished=true;if(auto*Q=QuestComponent.Get()){FTFGQuestState S;if(Q->GetQuestState(QuestId,S)&&!S.bCompleted)Q->CompleteQuest(QuestId);}if(ObjectiveWidget)ObjectiveWidget->SetObjective(FText::FromString(TEXT("PALACE APPROACH SECURED")),FText::FromString(TEXT("The next path leads deeper into the royal halls.")));}
